+         if(env.RELEASE_MODE==='checks')assert.notEqual(env.PUBLISH,'true','checks dispatch cannot request registry publication');
+         else assert.equal(env.PUBLISH,'true','explicit publication also requires push');
+        }
+        const called=env.EVENT==='workflow_call';
+        const event=called||env.EVENT==='push'?'workflow_dispatch':env.EVENT;
+        if(event==='workflow_run'&&env.RUN_CONCLUSION!=='success') {
+         appendFileSync(env.GITHUB_OUTPUT,'build=false\npublish=false\ntag=\n');process.exit(0);
+        }
+        if(env.PUBLISH==='true')assert.equal(env.CUSTOM_REF,'','publication cannot select an arbitrary custom source');
+        const decision=resolvePackageRelease({...env,EVENT:event});
