+        EVENT: ${{ github.event_name }}
+        CHECKS_MODE: ${{ inputs.mode }}
+        RELEASE_MODE: ${{ inputs.release_mode }}
+        REPOSITORY: ${{ github.repository }}
+        REFERENCE: ${{ github.ref }}
